Running command: cat > /workspace/test_poc.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <oniguruma.h>

int main(int argc, char* argv[]) {
    int r;
    unsigned char *pattern, *str;
    regex_t* reg;
    OnigErrorInfo einfo;
    OnigRegion *region;

    static UChar* patterns[] = {
        (UChar*)"(?<=(a))\\1",
        (UChar*)"(?<=(a)(b))\\1",
        (UChar*)"(?<=(a)|(b))\\1",
        (UChar*)"(?<=(?:a))",
        (UChar*)"(?<=(?1))",
        (UChar*)"(?<=(a)(?1))",
        (UChar*)"(?<=(?1)(a))",
        (UChar*)"(?<=(a)(b)(c))\\1",
        (UChar*)"(?<=(a)(b)(c)(d))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e)(f))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e)(f)(g))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e)(f)(g)(h))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e)(f)(g)(h)(i))\\1",
        (UChar*)"(?<=(a)(b)(c)(d)(e)(f)(g)(h)(i)(j))\\1",
        NULL
    };

    onig_initialize(&OnigEncDefaultCharEncoding, 1);

    for (int i = 0; patterns[i] != NULL; i++) {
        r = onig_new(&reg, patterns[i], patterns[i] + strlen((char*)patterns[i]),
                     ONIG_OPTION_DEFAULT, ONIG_ENCODING_UTF8, ONIG_SYNTAX_DEFAULT, &einfo);
        if (r == ONIG_NORMAL) {
            printf("Pattern %d compiled OK\n", i);
            onig_free(reg);
        } else {
            char s[ONIG_MAX_ERROR_MESSAGE_LEN];
            onig_error_code_to_str((UChar*)s, r, &einfo);
            printf("Pattern %d error: %s\n", i, s);
        }
    }

    onig_end();
    return 0;
}
EOF
